// client/ui-registration.ts
function registerUi(context) {
  const cleanups = [];
  cleanups.push(
    context.addAgentPanel({
      id: "sidechat",
      title: messages.message("panel.title"),
      icon: "MessageCircleQuestion",
      locations: ["explorer"],
      Component: BtwPanel
    })
  );
  const chiefView = new URLSearchParams(
    globalThis.location?.search ?? ""
  ).get("view") === "chief";
  if (!chiefView)
    cleanups.push(
      context.addSlashCommand({
        name: "btw",
        description: messages.message("commands.btwDescription"),
        argumentHint: "<question>",
        context: "agent",
        async onSubmit({ args, agent, rpc, openPanel }) {
          const question = args.trim();
          if (!question) {
            throw new Error(context.i18n.t(messages, "commands.btwUsage"));
          }
          await rpc(btwAsk, { agentId: agent.id, question });
          openPanel("sidechat", { location: "explorer" });
        }
      })
    );
  cleanups.push(
    context.addSlashCommand({
      name: "side",
      description: messages.message("commands.sideDescription"),
      argumentHint: "<task>",
      context: "agent",
      async onSubmit({ args, agent, rpc, openPanel }) {
        const question = args.trim();
        if (!question) {
          throw new Error(context.i18n.t(messages, "commands.sideUsage"));
        }
        await rpc(btwAsk, { agentId: agent.id, question, mode: "work" });
        openPanel("sidechat", { location: "explorer" });
      }
    })
  );
  cleanups.push(
    context.addSlashCommand({
      name: "fork",
      description: messages.message("commands.forkDescription"),
      argumentHint: "[first prompt]",
      context: "agent",
      async onSubmit({ args, agent, paseo }) {
        const page = await paseo.agents.ref(agent.id).timeline.refetch({ direction: "tail", limit: 200, projection: "canonical" });
        const lines = [
          context.i18n.t(messages, "commands.forkIntro", { title: agent.title ?? agent.id })
        ];
        for (const entry of page.entries) {
          const item = entry.item;
          if (item.type === "user_message") {
            lines.push(`\u7528\u6237: ${item.text}`);
          } else if (item.type === "assistant_message") {
            lines.push(`\u52A9\u624B: ${item.text}`);
          }
        }
        await paseo.workspaces.ref(agent.workspaceId).agents.create({
          config: {
            provider: agent.model ? `${agent.provider}/${agent.model}` : agent.provider
          },
          title: `Fork \xB7 ${agent.title ?? agent.id}`,
          prompt: args.trim() || void 0,
          attachments: [
            {
              type: "text",
              mimeType: "text/plain",
              title: context.i18n.t(messages, "commands.forkTranscriptTitle", {
                title: agent.title ?? agent.id
              }),
              text: lines.join("\n\n")
            }
          ]
        });
      }
    })
  );
  cleanups.push(
    context.addCommandCenterItem({
      id: "open-btw",
      title: messages.message("commands.openPanel"),
      icon: "MessageCircleQuestion",
      keywords: ["btw", "side", "sidechat", "ask", "\u65C1\u8DEF", "\u4FA7\u804A"],
      context: "agent",
      onSelect({ openPanel }) {
        openPanel("sidechat", { location: "explorer" });
      }
    })
  );
  cleanups.push(
    context.addCommandCenterItem({
      id: "open-btw-settings",
      title: messages.message("commands.openSettings"),
      icon: "Settings2",
      keywords: ["btw", "sidechat", "settings", "\u8BBE\u7F6E", "\u56DE\u6536"],
      context: "global",
      onSelect({ openSettings }) {
        openSettings("settings");
      }
    })
  );
  cleanups.push(
    context.addSettingsScreen({
      id: "settings",
      title: messages.message("panel.title"),
      icon: "Settings2",
      Component: BtwSettingsScreen
    })
  );
  return () => {
    for (const dispose of cleanups) dispose();
  };
}

// index.client.tsx
function contribute(client) {
  return registerUi(client);
}
export {
  contribute as default
};
